def transform(grid):
    g=[row[:] for row in grid]
    h=len(g); w=len(g[0])
    if any(7 in row and 2 in row for row in g):
        g[0]=[8]*w
    else:
        for r in range(h): g[r][w-1]=8
    return g

def transform(grid):
    g=[row[:] for row in grid]
    h=len(g); w=len(g[0])
    if any(any(g[r][c]==7 for r in range(h)) and any(g[r][c]==2 for r in range(h)) for c in range(w)):
        for r in range(h): g[r][w-1]=8
    else:
        g[0]=[8]*w
    return g
